// Generated by vibelang from src/TurnLog.ts; the migrate flow writes it again with each batch.
/**
 * Count and trace the turns a model double serves.
 *
 * A test that drives an install out of process cannot see which model turns
 * the install asked for. A turn log records each one as it is dispatched: its
 * name (the scripted step that answered it, or what the test names it), its
 * model, its message count, and optionally every message's text. `summary`
 * counts them by kind and name; `ModelServer` serves it at
 * `GET /__testing/turns`. With a file, each entry is also appended to it as
 * one JSON line, so the trace survives the server as test evidence.
 *
 * An entry never holds a request header, so it never holds a credential.
 *
 * @since 1.0.0
 */
import * as Model from "@smthrs/model/Model";
import { Effect, Ref, Stream } from "effect";
import { appendFileSync } from "node:fs";
import * as ScriptedModel from "./ScriptedModel.js";
/**
 * Builds an empty turn log.
 *
 * @category constructors
 * @since 1.0.0
 */
export const make = (options = {}) => Effect.gen(function* () {
    const state = yield* Ref.make([]);
    const record = (kind, step, detail = {}) => Ref.modify(state, (entries) => {
        const entry = { ...detail, n: entries.length + 1, at: new Date().toISOString(), kind, step };
        return [entry, [...entries, entry]];
    }).pipe(Effect.flatMap((entry) => options.file === undefined
        ? Effect.void
        : Effect.sync(() => appendFileSync(options.file, `${JSON.stringify(entry)}\n`, { mode: 0o600 }))));
    const chat = (request, step, detail = {}) => record("chat", step, {
        model: request.modelId,
        messageCount: request.messages.length,
        ...(options.messages === true ? { messages: ScriptedModel.transcript(request) } : {}),
        ...detail
    });
    const entries = () => Ref.get(state);
    const summary = () => Effect.map(Ref.get(state), (all) => {
        const steps = {};
        for (const entry of all)
            steps[entry.step] = (steps[entry.step] ?? 0) + 1;
        const count = (kind) => all.filter((entry) => entry.kind === kind).length;
        return {
            total: all.length,
            chat: count("chat"),
            evaluation: count("evaluation"),
            refused: count("refused"),
            steps
        };
    });
    return { chat, record, entries, summary };
});
/**
 * Wraps a model so each turn is logged under `step(request)` when it is
 * dispatched.
 *
 * @category constructors
 * @since 1.0.0
 */
export const model = (inner, options) => Model.make({
    ...(inner.providerName === undefined ? {} : { providerName: inner.providerName }),
    stream: (request) => Stream.unwrap(options.log.chat(request, options.step(request)).pipe(Effect.as(inner.stream(request))))
});
/**
 * Wraps an evaluator so each evaluation is logged under its question ids:
 * `evaluation` with its answers, or `refused` with the failure's message.
 *
 * @category constructors
 * @since 1.0.0
 */
export const evaluator = (inner, options) => ({
    evaluate: (request) => {
        const step = Object.keys(request.questions).join(",") || "empty";
        return inner.evaluate(request).pipe(Effect.tap((response) => options.log.record("evaluation", step, { answers: response.answers })), Effect.tapError((error) => options.log.record("refused", step, { error: error.message })));
    }
});
